| policy_sql                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |
| CREATE POLICY "Users can view related alerts" ON public.alerts AS PERMISSIVE FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1<br>   FROM donors<br>  WHERE ((donors.id = alerts.donor_id) AND (donors.profile_id = auth.uid())))) OR (EXISTS ( SELECT 1<br>   FROM blood_requests<br>  WHERE ((blood_requests.id = alerts.request_id) AND (blood_requests.requester_profile_id = auth.uid()))))));                                                 |
| CREATE POLICY "Authenticated users can view configuration" ON public.app_config AS PERMISSIVE FOR SELECT TO authenticated USING (true);                                                                                                                                                                                                                                                                                                                  |
| CREATE POLICY "Users can view own audit entries" ON public.audit_log AS PERMISSIVE FOR SELECT TO authenticated USING ((actor_id = auth.uid()));                                                                                                                                                                                                                                                                                                          |
| CREATE POLICY "Requesters can create requests" ON public.blood_requests AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((requester_profile_id = auth.uid()) AND (status = 'Pending'::text) AND (EXISTS ( SELECT 1<br>   FROM profiles<br>  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'Requester'::text) AND (profiles.account_status = 'Active'::text))))));                                                                         |
| CREATE POLICY "Users can view own requests" ON public.blood_requests AS PERMISSIVE FOR SELECT TO authenticated USING ((requester_profile_id = auth.uid()));                                                                                                                                                                                                                                                                                              |
| CREATE POLICY "Facility owners can view blood units" ON public.blood_units AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM facilities<br>  WHERE ((facilities.id = blood_units.facility_id) AND (facilities.owner_profile_id = auth.uid())))));                                                                                                                                                                           |
| CREATE POLICY "Users can view related donations" ON public.donations AS PERMISSIVE FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1<br>   FROM donors<br>  WHERE ((donors.id = donations.donor_id) AND (donors.profile_id = auth.uid())))) OR (EXISTS ( SELECT 1<br>   FROM facilities<br>  WHERE ((facilities.id = donations.facility_id) AND (facilities.owner_profile_id = auth.uid()))))));                                                    |
| CREATE POLICY "Donors can create own record" ON public.donors AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((profile_id = auth.uid()) AND (reliability_level = 'Medium'::text)));                                                                                                                                                                                                                                                               |
| CREATE POLICY "Donors can update own record" ON public.donors AS PERMISSIVE FOR UPDATE TO authenticated USING ((profile_id = auth.uid())) WITH CHECK ((profile_id = auth.uid()));                                                                                                                                                                                                                                                                        |
| CREATE POLICY "Donors can view own record" ON public.donors AS PERMISSIVE FOR SELECT TO authenticated USING ((profile_id = auth.uid()));                                                                                                                                                                                                                                                                                                                 |
| CREATE POLICY "Donors can submit own reports" ON public.external_donation_reports AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((review_status = 'Pending'::text) AND (EXISTS ( SELECT 1<br>   FROM donors<br>  WHERE ((donors.id = external_donation_reports.donor_id) AND (donors.profile_id = auth.uid()))))));                                                                                                                              |
| CREATE POLICY "Donors can view own reports" ON public.external_donation_reports AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM donors<br>  WHERE ((donors.id = external_donation_reports.donor_id) AND (donors.profile_id = auth.uid())))));                                                                                                                                                                             |
| CREATE POLICY "Owners can update own facility details" ON public.facilities AS PERMISSIVE FOR UPDATE TO authenticated USING ((owner_profile_id = auth.uid())) WITH CHECK ((owner_profile_id = auth.uid()));                                                                                                                                                                                                                                              |
| CREATE POLICY "Owners can view own facilities" ON public.facilities AS PERMISSIVE FOR SELECT TO authenticated USING ((owner_profile_id = auth.uid()));                                                                                                                                                                                                                                                                                                   |
| CREATE POLICY "Users can register facilities" ON public.facilities AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((owner_profile_id = auth.uid()) AND (verification_status = 'Pending'::text) AND (EXISTS ( SELECT 1<br>   FROM profiles<br>  WHERE ((profiles.id = auth.uid()) AND (profiles.role = facilities.facility_type) AND (profiles.account_status = 'Active'::text))))));                                                              |
| CREATE POLICY "Facility owners can view related inquiries" ON public.inquiries AS PERMISSIVE FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1<br>   FROM facilities<br>  WHERE ((facilities.id = inquiries.hospital_facility_id) AND (facilities.owner_profile_id = auth.uid())))) OR (EXISTS ( SELECT 1<br>   FROM facilities<br>  WHERE ((facilities.id = inquiries.blood_bank_facility_id) AND (facilities.owner_profile_id = auth.uid())))))); |
| CREATE POLICY "Facility owners can view inventory transactions" ON public.inventory_transactions AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM facilities<br>  WHERE ((facilities.id = inventory_transactions.facility_id) AND (facilities.owner_profile_id = auth.uid())))));                                                                                                                                          |
| CREATE POLICY "Users can create own profile" ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((id = auth.uid()) AND (role = ANY (ARRAY['Donor'::text, 'Requester'::text, 'Hospital'::text, 'Blood Bank'::text])) AND (account_status = 'Active'::text)));                                                                                                                                                                       |
| CREATE POLICY "Users can view own profile" ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((id = auth.uid()));                                                                                                                                                                                                                                                                                                                       |
| CREATE POLICY "Donors can view own reliability outcomes" ON public.reliability_outcomes AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM donors<br>  WHERE ((donors.id = reliability_outcomes.donor_id) AND (donors.profile_id = auth.uid())))));                                                                                                                                                                          |
| CREATE POLICY "Users can view own request history" ON public.request_status_history AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM blood_requests<br>  WHERE ((blood_requests.id = request_status_history.request_id) AND (blood_requests.requester_profile_id = auth.uid())))));                                                                                                                                        |
| CREATE POLICY "Facility owners can view screening records" ON public.screening_records AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM (donations d<br>     JOIN facilities f ON ((f.id = d.facility_id)))<br>  WHERE ((d.id = screening_records.donation_id) AND (f.owner_profile_id = auth.uid())))));                                                                                                                  |
| CREATE POLICY "Facility owners can view stock thresholds" ON public.stock_thresholds AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1<br>   FROM facilities<br>  WHERE ((facilities.id = stock_thresholds.facility_id) AND (facilities.owner_profile_id = auth.uid())))));                                                                                                                                                            |